/* @lc app=leetcode id=4055 lang=kotlin */ class Solution { fun go(v: List<Int>, lo: Int, hi: Int): Long = if (hi - lo <= 1 || v.size < 2) 0L else ((lo + hi) / 2).let { mid -> ArrayList<Int>().let { ss -> ArrayList<Int>().let { ls -> v.indices.sumOf { t -> v[t].let { e -> if (e < mid) generateSequence { ss.lastOrNull()?.takeIf { v[it] < e } }.forEach { _ -> ss.removeAt(ss.size - 1) }.let { ss.add(t) }.let { 0L } else generateSequence { ls.lastOrNull()?.takeIf { v[it] >= e } }.forEach { _ -> ls.removeAt(ls.size - 1) }.let { (ls.lastOrNull() ?: -1).let { p -> (ss.size + ss.binarySearch(p) + 1).toLong().also { ls.add(t) } } } } } + go(v.filter { it < mid }, lo, mid) + go(v.filter { it >= mid }, mid, hi) } } } fun shadowPairs(nums: IntArray): Int = nums.toSet().sorted().let { u -> go(nums.map { u.binarySearch(it) }, 0, u.size).toInt() } }